= LittlerootTown_ProfessorBirchsLab_EventScript_Birch
lock
faceplayer
goto_if_eq VAR_DEX_UPGRADE_JOHTO_STARTER_STATE 5 LittlerootTown_ProfessorBirchsLab_EventScript_CanHaveAnyOneOfRarePokemon
goto_if_eq VAR_DEX_UPGRADE_JOHTO_STARTER_STATE 2 LittlerootTown_ProfessorBirchsLab_EventScript_GrassyPatchWaiting
goto_if_unset FLAG_HAS_MATCH_CALL LittlerootTown_ProfessorBirchsLab_EventScript_TryRatePokedexOrRegister
goto_if_unset FLAG_ENABLE_PROF_BIRCH_MATCH_CALL EventScript_RegisterProfBirch
goto LittlerootTown_ProfessorBirchsLab_EventScript_TryRatePokedexOrRegister
end
= LittlerootTown_ProfessorBirchsLab_EventScript_TryRatePokedexOrRegister
goto_if_unset FLAG_HIDE_LITTLEROOT_TOWN_BIRCHS_LAB_UNKNOWN_0x380 ProfBirch_EventScript_RatePokedexOrRegister
goto_if_eq VAR_DEX_UPGRADE_JOHTO_STARTER_STATE 3 ProfBirch_EventScript_RatePokedexOrRegister
goto_if_ge VAR_DEX_UPGRADE_JOHTO_STARTER_STATE 6 ProfBirch_EventScript_RatePokedexOrRegister
goto_if_eq VAR_BIRCH_LAB_STATE 5 LittlerootTown_ProfessorBirchsLab_EventScript_PokemonAwait
msgbox	PROF. BIRCH: RIVAL? Gone home, I think.Or maybe that kid's scrabbling around in tall grass again somewhere…If you or your POKéMON get tired, you should get some rest at home.
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_PokemonAwait
msgbox	PROF. BIRCH: Countless POKéMON await you!Argh, I'm getting the itch to get out and do fieldwork again!
release
end
= ProfBirch_EventScript_RatePokedexOrRegister
lock
faceplayer
goto_if_unset FLAG_HAS_MATCH_CALL ProfBirch_EventScript_AskRatePokedex
goto_if_unset FLAG_ENABLE_PROF_BIRCH_MATCH_CALL EventScript_RegisterProfBirch
goto ProfBirch_EventScript_AskRatePokedex
= ProfBirch_EventScript_AskRatePokedex
msgbox	gBirchDexRatingText_AreYouCurious
goto_if_eq VAR_RESULT NO ProfBirch_EventScript_DeclineRating
call ProfBirch_EventScript_RatePokedex
release
end
= ProfBirch_EventScript_RatePokedex
setvar VAR_0x8004 0
specialvar VAR_RESULT ScriptGetPokedexInfo
copyvar VAR_0x8008 VAR_0x8005
copyvar VAR_0x8009 VAR_0x8006
copyvar VAR_0x800A VAR_RESULT
buffernumberstring STR_VAR_1 VAR_0x8008  @ Num Hoenn seen
buffernumberstring STR_VAR_2 VAR_0x8009  @ Num Hoenn caught
msgbox	gBirchDexRatingText_SoYouveSeenAndCaught
call ProfBirch_EventScript_ShowRatingMessage
goto_if_eq VAR_0x800A 0 Common_EventScript_NopReturn  @ National dex not enabled
setvar VAR_0x8004 1
specialvar VAR_RESULT ScriptGetPokedexInfo
copyvar VAR_0x8008 VAR_0x8005
copyvar VAR_0x8009 VAR_0x8006
buffernumberstring STR_VAR_1 VAR_0x8008  @ Num National seen
buffernumberstring STR_VAR_2 VAR_0x8009  @ Num National caught
msgbox	gBirchDexRatingText_OnANationwideBasis
return
= ProfBirch_EventScript_ShowRatingMessage
copyvar VAR_0x8004 VAR_0x8009
special ShowPokedexRatingMessage
waitmessage
waitbuttonpress
return
= ProfBirch_EventScript_DeclineRating
msgbox	gBirchDexRatingText_Cancel
release
end
= EventScript_RegisterProfBirch
msgbox	MatchCall_Text_BirchRegisterCall
closemessage
delay 30
playfanfare MUS_REGISTER_MATCH_CALL
msgbox	MatchCall_Text_RegisteredBirch
waitfanfare
closemessage
delay 30
setflag FLAG_ENABLE_PROF_BIRCH_MATCH_CALL
setvar VAR_REGISTER_BIRCH_STATE 2
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_GrassyPatchWaiting
msgbox	PROF. BIRCH: But listen. You've become the CHAMPION, but your POKéMON journey isn't over.There is no end to the road that is POKéMON.Somewhere, there is a grassy patch that's waiting for you!
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_CanHaveAnyOneOfRarePokemon
msgbox	PROF. BIRCH: These are rare POKéMON only found in another region!You can have any one of these three POKéMON!
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_Aide
lock
faceplayer
goto_if_ge VAR_BIRCH_LAB_STATE 3 LittlerootTown_ProfessorBirchsLab_EventScript_AideReceivedStarter
goto_if_set FLAG_BIRCH_AIDE_MET LittlerootTown_ProfessorBirchsLab_EventScript_AideAlreadyMet
msgbox	Hunh? PROF. BIRCH?The PROF's away on fieldwork. Ergo, he isn't here.Oh, let me explain what fieldwork is.It is to study things in the natural environment, like fields and mountains, instead of a laboratory.The PROF isn't one for doing desk work. He's the type of person who would rather go outside and experience things than read about them here.
setflag FLAG_BIRCH_AIDE_MET
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_AideAlreadyMet
msgbox	The PROF isn't one for doing desk work. He's the type of person who would rather go outside and experience things than read about them here.
release
end
= LittlerootTown_ProfessorBirchsLab_EventScript_AideReceivedStarter
msgbox	PROF. BIRCH is studying the habitats and distribution of POKéMON.The PROF enjoys RIVAL's help, too. There's a lot of love there.
release
end
